// Determine which declarations are due this month based on the user's TVA regime
const cfg = $json;
const now = new Date();
const Y = now.getFullYear();
const M = now.getMonth() + 1; // 1-12
const pad = (n) => String(n).padStart(2, '0');
const declarations = [];

// Helper: build period & deadline
function addDecl(type, period, deadline, periodStart, periodEnd) {
  declarations.push({ type, period, deadline, period_start: periodStart, period_end: periodEnd });
}

if (cfg.tva_regime === 'mensuel') {
  // CA3 mensuelle pour le mois précédent — deadline le 19 de ce mois
  const prev = new Date(Y, M - 2, 1);
  const py = prev.getFullYear();
  const pm = prev.getMonth() + 1;
  const period = `${py}-${pad(pm)}`;
  const deadline = `${Y}-${pad(M)}-19`;
  const start = `${py}-${pad(pm)}-01`;
  const end = new Date(py, pm, 0).toISOString().slice(0, 10);
  addDecl('tva_ca3', period, deadline, start, end);
} else if (cfg.tva_regime === 'trimestriel') {
  // CA3 trimestrielle quand le mois courant est avril, juillet, octobre, janvier
  const trimMonths = { 4: ['T1', 1, 3], 7: ['T2', 4, 6], 10: ['T3', 7, 9], 1: ['T4', 10, 12] };
  if (trimMonths[M]) {
    const [trimLabel, ms, me] = trimMonths[M];
    const py = M === 1 ? Y - 1 : Y;
    const period = `${py}-${trimLabel}`;
    const deadline = `${Y}-${pad(M)}-19`;
    const start = `${py}-${pad(ms)}-01`;
    const end = new Date(py, me, 0).toISOString().slice(0, 10);
    addDecl('tva_ca3', period, deadline, start, end);
  }
} else if (cfg.tva_regime === 'annuel') {
  // CA12 annuelle deadline début mai
  if (M === 5) {
    addDecl('tva_ca12', String(Y - 1), `${Y}-05-05`, `${Y - 1}-01-01`, `${Y - 1}-12-31`);
  }
}

// Acomptes IS : 15 mars, 15 juin, 15 sept, 15 déc
if ([3, 6, 9, 12].includes(M)) {
  addDecl('is', `${Y}-acompte-${pad(M)}`, `${Y}-${pad(M)}-15`, `${Y}-01-01`, `${Y}-${pad(M)}-${pad(new Date(Y, M, 0).getDate())}`);
}

// Liasse + IS solde : 2e jour ouvré suivant le 1er mai
if (M === 5) {
  addDecl('liasse', String(Y - 1), `${Y}-05-15`, `${Y - 1}-01-01`, `${Y - 1}-12-31`);
}

// CFE : 15 décembre
if (M === 12) {
  addDecl('cfe', String(Y), `${Y}-12-15`, `${Y}-01-01`, `${Y}-12-31`);
}

if (declarations.length === 0) return [{ json: { ...cfg, _skip: true } }];
return declarations.map((d) => ({ json: { ...cfg, _decl: d } }));

// Pre-aggregate to keep the Claude prompt small
const ctx = $('Determine due').item.json;
const txs = $json || [];
const byBase = { 20: { ht: 0, tva: 0 }, 10: { ht: 0, tva: 0 }, 5.5: { ht: 0, tva: 0 }, 2.1: { ht: 0, tva: 0 }, 0: { ht: 0, tva: 0 } };
let collectee = 0, deductible = 0, ca = 0, charges = 0;
for (const t of txs) {
  const amt = Number(t.amount) || 0;
  const ht = Number(t.ht_amount) || 0;
  const tva = Number(t.tva_amount) || 0;
  const rate = Number(t.tva_rate) || 0;
  const isCredit = t.type === 'credit' || amt > 0;
  if (isCredit) {
    ca += Math.abs(amt);
    collectee += tva;
    if (byBase[rate]) byBase[rate].ht += Math.abs(ht || amt);
    if (byBase[rate]) byBase[rate].tva += tva;
  } else {
    charges += Math.abs(amt);
    if (t.tva_deductible) deductible += tva;
  }
}
return [{ json: {
  ...ctx,
  _summary: {
    tx_count: txs.length,
    ca,
    charges,
    tva_collectee: Math.round(collectee * 100) / 100,
    tva_deductible: Math.round(deductible * 100) / 100,
    tva_nette: Math.round((collectee - deductible) * 100) / 100,
    base_ht_20: Math.round(byBase[20].ht * 100) / 100,
    base_ht_10: Math.round(byBase[10].ht * 100) / 100,
    base_ht_5_5: Math.round(byBase[5.5].ht * 100) / 100,
    base_ht_2_1: Math.round(byBase[2.1].ht * 100) / 100,
    base_ht_0: Math.round(byBase[0].ht * 100) / 100,
  }
} }];

