const ctx = $('Aggregate transactions').item.json;
const raw = $json.content?.[0]?.text || '{}';
let a = { calculated_data: {}, ai_notes: '', ai_optimizations: [] };
try { const m = raw.match(/\{[\s\S]*\}/); a = { ...a, ...JSON.parse(m ? m[0] : raw) }; } catch (e) { a.ai_notes = 'parse error'; }
return [{ json: {
  user_id: ctx.user_id,
  type: ctx._decl.type,
  period: ctx._decl.period,
  status: 'ready',
  calculated_data: a.calculated_data || ctx._summary,
  ai_notes: a.ai_notes || '',
  ai_optimizations: a.ai_optimizations || [],
  deadline: ctx._decl.deadline,
} }];
